input.content:
import { chromium } from 'playwright';
const OUT = '/tmp/claude-1000/-home-parallels-dev-ivue/566fe626-e30e-4195-b057-18d7724adbb0/scratchpad';
const BASE = 'http://localhost:5188';
const browser = await chromium.launch();
try {
  const shots = [
    // phone: list mode (default), search row, toggle
    { name: 'phone-blog-list', w: 390, h: 844, url: '/blog/', full: false },
    { name: 'phone-blog-cards', w: 390, h: 844, url: '/blog/', full: false, cards: true },
    // phone: bottom of a post — author, share, quickjoin stacked, related
    { name: 'phone-post-bottom', w: 390, h: 844, url: '/blog/derivations-are-free', scrollTo: '.blog-author', full: false, tall: 1700 },
    // ipad mini portrait nav
    { name: 'ipadmini-nav', w: 768, h: 1024, url: '/blog/', full: false, clip: { x: 0, y: 0, width: 768, height: 72 } },
    // ipad pro portrait list
    { name: 'ipadpro-blog-list', w: 1024, h: 1366, url: '/blog/', full: false },
    // desktop post: aside (no share), author + share inline, no pill
    { name: 'desktop-post-bottom', w: 1440, h: 900, url: '/blog/derivations-are-free', scrollTo: '.blog-author', full: false, tall: 1100 },
    { name: 'desktop-blog-sidebar', w: 1440, h: 900, url: '/blog/', full: false },
    // desktop toast: force open on a guide page
    { name: 'desktop-toast', w: 1440, h: 900, url: '/guide/introduction', toast: true, full: false },
  ];
  for (const s of shots) {
    const page = await browser.newPage({ viewport: { width: s.w, height: s.tall ?? s.h }, colorScheme: 'dark' });
    await page.goto(BASE + s.url, { waitUntil: 'networkidle' });
    if (s.cards) { await page.click('button[aria-label="Card view"]'); await page.waitForTimeout(200); }
    if (s.toast) { await page.click('.newsletter-pill'); await page.waitForTimeout(600); }
    if (s.scrollTo) { await page.locator(s.scrollTo).scrollIntoViewIfNeeded(); await page.evaluate(() => window.scrollBy(0, -80)); await page.waitForTimeout(400); }
    await page.screenshot({ path: `${OUT}/${s.name}.png`, fullPage: s.full, clip: s.clip });
    await page.close();
  }
  // data probes
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(BASE + '/blog/derivations-are-free', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  const probe = await page.evaluate(() => ({
    pill: !!document.querySelector('.newsletter-pill'),
    asideShare: !!document.querySelector('.blog-share--aside'),
    docShare: getComputedStyle(document.querySelector('.blog-share--doc')).display,
    orderAfterAuthor: document.querySelector('.blog-author')?.nextElementSibling?.className,
    sidebarFont: getComputedStyle(document.querySelector('.VPSidebar .VPSidebarItem.level-1 .link .text')).fontSize,
    railSearch: !!document.querySelector('.blog-rail-search__input'),
    localNav: document.querySelector('.VPLocalNav .menu .menu-text')?.textContent,
  }));
  console.log(JSON.stringify(probe, null, 2));
  await page.goto(BASE + '/guide/introduction', { waitUntil: 'networkidle' });
  await page.waitForTimeout(800);
  console.log('guide pill:', await page.evaluate(() => !!document.querySelector('.newsletter-pill')));
  // sidebar search on a post navigates to the index filtered
  await page.goto(BASE + '/blog/derivations-are-free', { waitUntil: 'networkidle' });
  await page.fill('.blog-rail-search__input', 'signals');
  await page.waitForTimeout(900);
  console.log('after typing:', page.url(), await page.evaluate(() => ({
    idx: document.querySelector('.blog-search__input')?.value,
    count: document.querySelector('.blog-search__count')?.textContent?.trim(),
    clearBtns: document.querySelectorAll('.blog-search__clear, .blog-rail-search__clear').length,
  })));
  await page.goto(BASE + '/blog/?q=getter', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  console.log('q param:', await page.evaluate(() => document.querySelector('.blog-search__count')?.textContent?.trim()));
} finally {
  await browser.close();
}

